const M=window.StoquifyModel,root=document.getElementById("app"),dialog=document.getElementById("review-dialog");
const state={locale:"en",view:"builder",preset:"retailer",selected:[...M.presets.retailer.selected],category:"all",query:"",external:false,setup:false,licensed:true,fail:false,role:"owner",screen:"ready",revision:1,observed:M.plan(["sales","finance"]).resolved,history:[],previewDraft:false,applying:false};
const t=(en,fr)=>state.locale==="fr"?fr:en,e=s=>String(s).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
const tr=obj=>obj[state.locale],by=id=>M.manifests.find(m=>m.id===id)||(id==="external_ledger"?M.externalLedger:null),name=id=>by(id)?tr(by(id).name):id;
const icons={inventory:"▦",sales:"↗",pos:"▣",cash_drawer:"◉",purchasing:"⇄",finance:"◈",accounting:"≡",payment_reconciliation:"⇌",close_assurance:"✓",hris:"◎",presence:"◷",payroll:"▤",compliance:"◇",reports:"▥",analytics:"⌁",commercial_agents:"↗",content:"▧",agent_assistance:"✧"};
function plan(){return M.plan([...state.selected,...(state.external?["external_ledger"]:[])],{registry:state.external?[...M.manifests,M.externalLedger]:M.manifests,prerequisites:{country_pack_verified:state.setup,responsible_owner:state.setup,agent_policy:state.setup},...(state.licensed?{}:{licensed:state.observed})})}
function toast(message){document.querySelector(".toast")?.remove();const node=document.createElement("div");node.className="toast";node.setAttribute("role","status");node.textContent=message;document.body.append(node);setTimeout(()=>node.remove(),4500)}
function issueText(issue){
if(issue.code==="CONFLICT")return t("Two ledger authorities cannot own the same posting. Keep the built-in ledger for this configuration.","Deux autorités ne peuvent pas posséder la même écriture. Conservez le grand livre intégré.");
if(issue.code==="SETUP")return name(issue.module)+": "+t("reviewed country/operating setup is needed.","la configuration pays ou opérationnelle doit être validée.");
if(issue.code==="LICENSE")return name(issue.module)+": "+t("subscription eligibility must be confirmed.","les droits de souscription doivent être confirmés.");
return t("Configuration requires review: ","Configuration à revoir : ")+issue.code;
}
const labels={builder:()=>t("Build workspace","Configurer"),workspace:()=>t("Workspace","Espace de travail"),history:()=>t("Change history","Historique")};
function render(){
const focusId=document.activeElement?.id;
document.documentElement.lang=state.locale;
const p=plan(),preset=M.presets[state.preset],view=state.view;
root.innerHTML='<div class="shell"><aside class="sidebar"><div class="logo"><span class="logo-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span>stoquify</div><div class="tenant-box"><b>'+e(tr(preset.organization))+'</b>'+t("Organization workspace","Espace de l’organisation")+'</div><nav aria-label="'+t("Main navigation","Navigation principale")+'"><p class="side-caption">'+t("Workspace","Espace de travail")+'</p><div class="side-nav">'+["builder","workspace","history"].map((v,i)=>'<button id="nav-'+v+'" data-view="'+v+'" class="'+(view===v?"active":"")+'" '+(view===v?'aria-current="page"':"")+'><span class="nav-icon" aria-hidden="true">'+["▦","◈","◷"][i]+'</span>'+labels[v]()+'</button>').join("")+'</div></nav><div class="side-bottom">'+t("One platform.<br>Your way of working.","Une plateforme.<br>Votre façon de travailler.")+'<p class="small" style="margin-top:14px">'+t("Astra design study · September 2026","Étude Astra · septembre 2026")+'</p></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><span class="muted">'+t("Settings","Paramètres")+'</span> &nbsp; / &nbsp; '+labels[view]()+'</div><div class="topbar-right"><span class="badge green">'+t("Draft","Brouillon")+' · '+state.revision+'</span><button id="language" aria-label="'+t("Switch to French","Passer en anglais")+'">'+(state.locale==="en"?"FR":"EN")+'</button><span class="avatar" aria-label="Alex">AL</span></div></header><div class="prototype-band">'+t("Design prototype · Synthetic data · All activation and subscription changes are simulated.","Prototype de conception · Données fictives · Activations et souscriptions simulées.")+'</div><main id="main" class="main" tabindex="-1">'+(view==="builder"?builder(p):view==="workspace"?workspace():history())+'</main></div></div>';
if(view==="builder")root.insertAdjacentHTML("beforeend",'<div class="mobile-actions"><span>'+p.resolved.filter(id=>by(id)?.commercial.kind==="selectable").length+' '+t("capabilities","fonctionnalités")+'</span><button id="mobile-review" class="primary">'+(p.compatible?t("Review configuration","Examiner la configuration"):t("Review conditions","Vérifier les conditions"))+'</button></div>');
bind();
if(focusId){const elem=document.getElementById(focusId);if(elem)elem.focus({preventScroll:true})}
}
function builder(p){
const visible=p.resolved.filter(id=>by(id)?.commercial.kind==="selectable"),foundations=p.resolved.filter(id=>by(id)?.commercial.kind==="included");
return '<div class="hero"><div class="hero-copy"><p class="eyebrow">'+t("Workspace composition","Composition de l’espace")+'</p><h1>'+t("Choose what your<br>business needs.","Choisissez ce dont<br>votre activité a besoin.")+'</h1><p>'+t("Start with an outcome. Stoquify connects the right capabilities and makes every dependency clear.","Partez d’un objectif. Stoquify relie les bonnes fonctionnalités et explique chaque dépendance.")+'</p></div><span class="badge">'+t("Configuration preview","Aperçu de configuration")+'</span></div><div class="steps">'+[t("Choose outcomes","Choisir"),t("Check compatibility","Vérifier"),t("Preview the change","Prévisualiser"),t("Open your workspace","Ouvrir l’espace")].map((s,i)=>'<span class="step '+(i===0?"current":"")+'"><i>'+(i+1)+'</i>'+s+'</span>').join("")+'</div><div class="row-between"><h2>'+t("Start with your business","Commencez par votre activité")+'</h2><span class="small muted">'+t("Five starting points, freely configurable","Cinq points de départ personnalisables")+'</span></div><div class="preset-list">'+Object.entries(M.presets).map(([id,pr],i)=>'<button id="preset-'+id+'" data-preset="'+id+'" class="preset '+(state.preset===id?"active":"")+'" aria-pressed="'+(state.preset===id)+'"><span class="index">0'+(i+1)+'</span><span>'+e(tr(pr.name))+'</span></button>').join("")+'</div><div class="builder"><section aria-labelledby="catalog-heading"><div class="catalog-header"><h2 id="catalog-heading">'+t("Your building blocks","Vos modules")+'</h2><input id="search" class="search" type="search" value="'+e(state.query)+'" placeholder="'+t("Find a capability…","Rechercher…")+'" aria-label="'+t("Find a capability","Rechercher une fonctionnalité")+'"></div><div class="filter-list" aria-label="'+t("Module categories","Catégories de modules")+'">'+[["all",t("All capabilities","Toutes")],["operations",t("Operations","Opérations")],["finance",t("Finance","Finance")],["people",t("People","Personnel")],["assurance",t("Assurance","Assurance")],["specialist",t("Specialist","Spécialiste")]].map(([id,l])=>'<button id="filter-'+id+'" data-category="'+id+'" class="filter '+(state.category===id?"active":"")+'" aria-pressed="'+(state.category===id)+'">'+l+'</button>').join("")+'</div><div class="card-grid" id="cards">'+cards(p)+'</div><div class="platform-note">'+t("Included foundations handle identity, access and audit. Financial integrity is included wherever a selected workflow creates financial records.","Le socle inclus gère identité, accès et audit. L’intégrité financière est incluse pour les processus produisant des écritures.")+'</div></section><aside class="plan" aria-label="'+t("Configuration summary","Résumé de configuration")+'"><div class="plan-top"><p class="eyebrow">'+t("Your configuration","Votre configuration")+'</p><h2>'+e(tr(M.presets[state.preset].name))+'</h2><p class="small muted">'+e(tr(M.presets[state.preset].goal))+'</p><div class="stat-row"><div class="stat"><strong>'+visible.length+'</strong><span>'+t("business capabilities","fonctionnalités métier")+'</span></div><div class="stat"><strong>'+foundations.length+'</strong><span>'+t("included foundations","socles inclus")+'</span></div></div></div><div class="plan-body"><div class="foundation">✓ '+t("Shared identity, access & evidence","Identité, accès et preuves partagés")+'</div><div class="chip-list">'+visible.map(id=>'<span class="chip">'+e(name(id))+'</span>').join("")+'</div><details><summary>'+t("Why these parts are included","Pourquoi ces modules sont inclus")+'</summary><ul>'+p.automatic.filter(id=>id!=="platform").map(id=>'<li><b>'+e(name(id))+'</b> ← '+e([...new Set(p.reasons[id]||[])].map(name).join(", "))+'</li>').join("")+'</ul></details><div id="compatibility" class="status-panel '+(p.compatible?"":"issue")+'" role="status"><b>'+(p.compatible?"✓ ":"! ")+(p.compatible?t("These capabilities fit together","Ces fonctionnalités sont compatibles"):t("Review needed before activation","Vérification requise avant activation"))+'</b>'+(p.compatible?'<p class="hint">'+t("Required dependencies are present. Operating setup and commercial terms still need real verification before deployment.","Les dépendances sont présentes. La configuration et les conditions commerciales devront être vérifiées avant déploiement.")+'</p>':'<ul class="issue-list">'+[...new Set(p.issues.map(issueText))].map(s=>'<li>'+e(s)+'</li>').join("")+'</ul>')+(state.external?'<button id="resolve-ledger" class="wide">'+t("Keep the built-in ledger","Conserver le grand livre intégré")+'</button>':"")+'</div><div class="row-between small"><span class="muted">'+t("Price impact","Impact sur le prix")+'</span><b>'+t("Quote required","Devis requis")+'</b></div><p class="hint">'+t("No prices are assumed. Nothing is purchased here.","Aucun prix supposé. Aucun achat ici.")+'</p><hr class="divider"><button id="review" class="primary wide" '+(!p.compatible?"disabled":"")+'>'+t("Review configuration →","Examiner la configuration →")+'</button><button id="preview" class="wide" style="margin-top:8px">'+t("Preview planned workspace","Aperçu de l’espace prévu")+'</button><details><summary>'+t("Explore example conditions","Explorer les conditions de démonstration")+'</summary><label>'+t("Ledger connection","Connexion comptable")+'<select id="ledger"><option value="native" '+(!state.external?"selected":"")+'>'+t("Built-in authority","Autorité intégrée")+'</option><option value="external" '+(state.external?"selected":"")+'>'+t("External authority (illustrative conflict)","Autorité externe (conflit illustratif)")+'</option></select></label><label><input type="checkbox" id="setup" '+(state.setup?"checked":"")+'> '+t("Use completed setup in this demo","Simuler une configuration validée")+'</label><label><input type="checkbox" id="licensed" '+(state.licensed?"checked":"")+'> '+t("Simulate eligibility for selected capabilities","Simuler les droits des modules choisis")+'</label><label><input type="checkbox" id="fail" '+(state.fail?"checked":"")+'> '+t("Simulate a provisioning failure","Simuler un échec de préparation")+'</label></details></div></aside></div>';
}
function cards(p){
const filtered=M.manifests.filter(m=>m.commercial.kind==="selectable"&&(state.category==="all"||m.category===state.category)&&(tr(m.name)+" "+tr(m.summary)).toLocaleLowerCase().includes(state.query.toLocaleLowerCase()));
if(!filtered.length)return '<div class="catalog-empty">'+t("No capabilities match. Try another search.","Aucun résultat. Essayez une autre recherche.")+'</div>';
return filtered.map(m=>{const selected=p.resolved.includes(m.id),explicit=state.selected.includes(m.id),required=selected&&!explicit;
return '<article class="module-card '+(selected?"selected":"")+'"><div class="card-head"><span class="card-icon" aria-hidden="true">'+(icons[m.id]||"▦")+'</span><span class="badge '+(selected?"green":"")+'">'+(required?t("Required","Requis"):selected?t("Selected","Sélectionné"):t("Optional","Optionnel"))+'</span></div><h3>'+e(tr(m.name))+'</h3><p>'+e(tr(m.summary))+'</p><label><input id="module-'+m.id+'" type="checkbox" data-module="'+m.id+'" '+(selected?"checked":"")+' '+(required?"disabled":"")+' aria-label="'+e(t("Select ","Sélectionner ")+tr(m.name))+'">'+(required?t("Included dependency","Dépendance incluse"):t("Use this capability","Utiliser cette fonctionnalité"))+'</label>'+(required?'<div class="required-note">'+t("Needed by ","Nécessaire pour ")+e([...new Set(p.reasons[m.id]||[])].map(name).join(", "))+'</div>':"")+'</article>'}).join("");
}
function workspace(){
const config=state.previewDraft?plan().resolved:state.observed,allowedIds=state.role==="owner"?config:state.role==="operator"?config.filter(id=>["sales","inventory","pos","cash_drawer"].includes(id)):config.filter(id=>["finance","accounting","payment_reconciliation","close_assurance","reports"].includes(id));
const modules=allowedIds.filter(id=>by(id)?.commercial.kind==="selectable");
const selectedStates=[["ready",t("Ready","Prêt")],["loading",t("Loading","Chargement")],["empty",t("No activity","Aucune activité")],["denied",t("Permission denied","Accès refusé")],["unavailable",t("Unavailable capability","Module indisponible")],["partial",t("Partial data","Données partielles")],["error",t("Query failed","Échec de lecture")]];
let content='';
if(["loading","empty","denied","unavailable","error"].includes(state.screen)){const messages={loading:[t("Loading your workspace","Chargement de votre espace"),t("Waiting for the authorized data sources.","En attente des sources autorisées.")],empty:[t("No activity in this period","Aucune activité sur cette période"),t("Your configuration is available. There are no records for the selected scope.","Votre configuration est disponible. Aucun enregistrement dans ce périmètre.")],denied:[t("This operation needs permission","Cette opération nécessite un droit"),t("Module selection does not grant a person access. Ask the responsible owner to review your role.","Sélectionner un module ne donne pas un droit personnel. Faites vérifier votre rôle.")],unavailable:[t("This capability is unavailable","Cette fonctionnalité est indisponible"),t("Open configuration to see the dependency, subscription or setup condition.","Ouvrez la configuration pour consulter les conditions.")],error:[t("We could not load this view","Impossible de charger cette vue"),t("This is a query failure, not an empty result. Retry when the source recovers.","Il s’agit d’un échec de lecture, pas d’un résultat vide.")]}[state.screen];
content='<div class="empty-state screen-state" role="'+(state.screen==="error"?"alert":"status")+'"><div class="state-icon" aria-hidden="true">'+(state.screen==="loading"?"◌":"◇")+'</div><h2>'+messages[0]+'</h2><p class="muted">'+messages[1]+'</p><button id="retry-view">'+t("Return to ready example","Revenir à l’exemple prêt")+'</button></div>';
}else{
content=(state.screen==="partial"?'<div class="status-panel issue" role="status">'+t("Payment source delayed. Last reconciled values remain visible with their timestamp; no successful empty result is inferred.","Source de paiement retardée. Les dernières données restent datées ; aucun résultat vide n’est supposé.")+'</div>':"")+'<div class="workspace-grid"><div class="metric"><span class="small muted">'+t("Available to this role","Disponibles pour ce rôle")+'</span><strong>'+modules.length+'</strong><span class="badge green">'+t("Connected capabilities","Fonctionnalités reliées")+'</span></div><div class="metric"><span class="small muted">'+t("Items requiring attention","Éléments à traiter")+'</span><strong>'+Math.min(modules.length,4)+'</strong><span class="small muted">'+t("Synthetic demonstration queue","File de démonstration fictive")+'</span></div><div class="metric"><span class="small muted">'+t("Configuration revision","Révision de configuration")+'</span><strong>'+state.revision+'</strong><span class="small muted">'+t("One workspace, shared context","Un espace, un contexte partagé")+'</span></div></div><div class="work-grid"><section class="panel"><p class="eyebrow">'+t("Today’s work","Travail du jour")+'</p><h2>'+t("A connected work queue","Une file de travail unifiée")+'</h2><ul class="queue">'+modules.slice(0,4).map((id,i)=>'<li><span><b>'+e(name(id))+'</b><br><span class="muted">'+e(tr(by(id).summary))+'</span></span><span class="badge">'+(i+1)+'</span></li>').join("")+'</ul></section><section class="panel"><p class="eyebrow">'+t("Your workspace","Votre espace")+'</p><h2>'+t("One place to work","Un seul espace de travail")+'</h2><p class="muted small">'+t("Navigation is composed from your role and the effective configuration. Business data stays with its owning module.","La navigation combine votre rôle et la configuration effective. Chaque domaine conserve ses données.")+'</p><div class="workspace-modules">'+modules.map(id=>'<button data-open-module="'+id+'">'+e(name(id))+'</button>').join("")+'</div></section></div>';
}
return '<div class="hero"><div class="hero-copy"><p class="eyebrow">'+(state.previewDraft?t("Planned workspace preview","Aperçu de l’espace prévu"):t("Current simulated workspace","Espace simulé actuel"))+'</p><h1>'+e(tr(M.presets[state.preset].organization))+'</h1><p>'+e(tr(M.presets[state.preset].goal))+'</p></div><button data-view="builder">'+t("Edit configuration","Modifier la configuration")+'</button></div><div class="view-tools"><label>'+t("Role","Rôle")+'<select id="role">'+[["owner",t("Owner","Responsable")],["operator",t("Operator","Opérateur")],["accountant",t("Accountant","Comptable")]].map(([id,l])=>'<option value="'+id+'" '+(id===state.role?"selected":"")+'>'+l+'</option>').join("")+'</select></label><label>'+t("Example state","État de démonstration")+'<select id="screen">'+selectedStates.map(([id,l])=>'<option value="'+id+'" '+(id===state.screen?"selected":"")+'>'+l+'</option>').join("")+'</select></label></div>'+content+'<p class="hint" style="margin-top:22px">'+t("All identities, permissions, values and operating states on this screen are synthetic. Production access must be checked by the server for every operation.","Identités, droits, valeurs et états sont fictifs. Le serveur devra vérifier chaque opération en production.")+'</p>';
}
function history(){
return '<div class="hero"><div class="hero-copy"><p class="eyebrow">'+t("Configuration history","Historique des configurations")+'</p><h1>'+t("Every change has a story.","Chaque changement est traçable.")+'</h1><p>'+t("See what changed, what was preserved and how to return to a draft.","Consultez les changements, les éléments conservés et le retour au brouillon.")+'</p></div></div><section class="panel">'+(state.history.length?state.history.slice().reverse().map(h=>'<article class="activity"><h3>'+t("Simulation revision ","Révision simulée ")+h.revision+'</h3><p class="muted">'+e(h.time)+' · '+t("Synthetic owner","Responsable fictif")+'</p><p>'+t("Added: ","Ajouts : ")+e(h.added.map(name).join(", ")||"—")+'<br>'+t("Removed from new work: ","Retirés des nouveaux travaux : ")+e(h.removed.map(name).join(", ")||"—")+'</p><p class="small muted">'+t("Historical records remain under their original access and retention rules. No business data was changed.","Les historiques conservent leurs règles d’accès et de conservation. Aucune donnée métier modifiée.")+'</p><button data-restore="'+h.revision+'">'+t("Reopen the earlier draft","Rouvrir le brouillon précédent")+'</button></article>').join(""):'<div class="empty-state"><h2>'+t("No simulated changes yet","Aucun changement simulé")+'</h2><p class="muted">'+t("Review a configuration and simulate activation to see the change record.","Examinez une configuration puis simulez son activation.")+'</p><button data-view="builder">'+t("Build a configuration","Créer une configuration")+'</button></div>')+'</section>';
}
function bind(){
root.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{state.view=b.dataset.view;state.previewDraft=false;render();document.getElementById("main").focus({preventScroll:true})});
document.getElementById("language").onclick=()=>{state.locale=state.locale==="en"?"fr":"en";render()};
root.querySelectorAll("[data-preset]").forEach(b=>b.onclick=()=>{state.preset=b.dataset.preset;state.selected=[...M.presets[state.preset].selected];state.query="";state.category="all";state.external=false;render()});
root.querySelectorAll("[data-category]").forEach(b=>b.onclick=()=>{state.category=b.dataset.category;render()});
root.querySelectorAll("[data-module]").forEach(c=>c.onchange=()=>{state.selected=c.checked?[...new Set([...state.selected,c.dataset.module])]:state.selected.filter(id=>id!==c.dataset.module);render()});
const search=document.getElementById("search");if(search)search.oninput=()=>{state.query=search.value;document.getElementById("cards").innerHTML=cards(plan());bindCards()};
for(const key of ["setup","licensed","fail"]){const item=document.getElementById(key);if(item)item.onchange=()=>{state[key]=item.checked;render()}}
const ledger=document.getElementById("ledger");if(ledger)ledger.onchange=()=>{state.external=ledger.value==="external";render()};
const resolve=document.getElementById("resolve-ledger");if(resolve)resolve.onclick=()=>{state.external=false;render();toast(t("One ledger authority retained.","Une seule autorité comptable conservée."))};
const review=document.getElementById("review");if(review)review.onclick=showReview;
const mobileReview=document.getElementById("mobile-review");if(mobileReview)mobileReview.onclick=()=>{if(plan().compatible)showReview();else document.getElementById("compatibility").scrollIntoView({behavior:"auto",block:"center"})};
const preview=document.getElementById("preview");if(preview)preview.onclick=()=>{state.previewDraft=true;state.view="workspace";render();document.getElementById("main").focus()};
for(const key of ["role","screen"]){const item=document.getElementById(key);if(item)item.onchange=()=>{state[key]=item.value;render()}}
const retry=document.getElementById("retry-view");if(retry)retry.onclick=()=>{state.screen="ready";render()};
root.querySelectorAll("[data-open-module]").forEach(b=>b.onclick=()=>toast(name(b.dataset.openModule)+": "+t("illustrative destination; no live route opened.","destination illustrative ; aucune route réelle ouverte.")));
root.querySelectorAll("[data-restore]").forEach(b=>b.onclick=()=>{const h=state.history.find(x=>x.revision===Number(b.dataset.restore));state.selected=h.previous.filter(id=>!["platform","ledger_core"].includes(id));state.external=false;state.view="builder";render();toast(t("Earlier configuration reopened as a draft. History is preserved.","Configuration précédente rouverte en brouillon. Historique conservé."))});
}
function bindCards(){root.querySelectorAll("[data-module]").forEach(c=>c.onchange=()=>{state.selected=c.checked?[...new Set([...state.selected,c.dataset.module])]:state.selected.filter(id=>id!==c.dataset.module);render()})}
function showReview(){
const p=plan();if(!p.compatible)return;
const groups=[{label:t("Add","Ajouter"),ids:p.resolved.filter(id=>!state.observed.includes(id))},{label:t("Keep","Conserver"),ids:p.resolved.filter(id=>state.observed.includes(id))},{label:t("Stop new work","Arrêter les nouveaux travaux"),ids:state.observed.filter(id=>!p.resolved.includes(id))}];
dialog.innerHTML='<p class="eyebrow">'+t("Change impact","Impact du changement")+'</p><h2 id="review-title">'+t("Review before anything changes","Vérifiez avant tout changement")+'</h2><p class="muted">'+t("This preview compares the desired configuration with the current simulated workspace.","Cet aperçu compare la configuration souhaitée à l’espace simulé actuel.")+'</p><div class="dialog-columns">'+groups.map(g=>'<section><h3>'+g.label+'</h3><ul>'+g.ids.map(id=>'<li>'+e(name(id))+'</li>').join("")+'</ul>'+(!g.ids.length?"—":"")+'</section>').join("")+'</div><div class="foundation">'+t("Existing records remain protected. Removing a capability never deletes its business history.","Les enregistrements restent protégés. Retirer une fonctionnalité ne supprime jamais son historique.")+'</div><p class="small muted">'+t("Commercial terms, real approvals and operating evidence are outside this simulation. No purchase or live activation will occur.","Conditions commerciales, approbations et preuves réelles sont hors simulation. Aucun achat ni activation réelle.")+'</p><div id="progress-area" aria-live="polite"></div><div class="dialog-footer"><button id="cancel-review">'+t("Back","Retour")+'</button><button id="simulate" class="primary">'+t("Simulate activation","Simuler l’activation")+'</button></div>';
dialog.showModal();
const title=document.getElementById("review-title");title.tabIndex=-1;title.focus({preventScroll:true});dialog.scrollTop=0;
dialog.onkeydown=event=>{if(event.key!=="Tab")return;const focusable=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(!first){event.preventDefault();return}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};
document.getElementById("cancel-review").onclick=()=>dialog.close();document.getElementById("simulate").onclick=()=>simulate(state.fail);
}
async function simulate(fail){
if(state.applying)return;state.applying=true;const p=plan(),revision=state.revision;
document.getElementById("simulate").disabled=true;document.getElementById("cancel-review").disabled=true;
dialog.oncancel=event=>{if(state.applying)event.preventDefault()};
const steps=[t("Check compatibility","Vérifier la compatibilité"),t("Prepare included capabilities","Préparer les fonctionnalités"),t("Compose access and navigation","Composer accès et navigation"),t("Record the simulated revision","Enregistrer la révision simulée")];
for(let i=0;i<steps.length;i++){
document.getElementById("progress-area").innerHTML='<div class="progress-area"><b>'+steps[i]+'</b><div class="progress">'+steps.map((_,j)=>'<span class="'+(j<=i?"done":"")+'"></span>').join("")+'</div></div>';
await new Promise(resolve=>setTimeout(resolve,250));
if(fail&&i===1){state.applying=false;document.getElementById("progress-area").innerHTML='<div class="status-panel issue" role="alert">'+t("Setup failed. No configuration was activated. Retry reuses the same draft.","Préparation échouée. Aucune configuration activée. Réessayez avec le même brouillon.")+'</div>';document.getElementById("simulate").textContent=t("Retry simulation","Réessayer");document.getElementById("simulate").disabled=false;document.getElementById("simulate").onclick=()=>simulate(false);document.getElementById("cancel-review").disabled=false;return}
}
if(!M.transition("validated","provisioning",{revision,currentRevision:state.revision}).allowed){state.applying=false;dialog.close();toast(t("The draft changed. Review again.","Le brouillon a changé. Vérifiez à nouveau."));return}
state.history.push({revision:state.revision+1,time:new Date().toLocaleString(state.locale==="fr"?"fr-FR":"en-GB"),previous:[...state.observed],added:p.resolved.filter(id=>!state.observed.includes(id)),removed:state.observed.filter(id=>!p.resolved.includes(id))});
state.revision++;state.observed=[...p.resolved];state.applying=false;state.previewDraft=false;state.view="workspace";state.screen="ready";dialog.close();render();document.getElementById("main").focus();toast(t("Simulation complete. Your workspace preview is ready.","Simulation terminée. Votre aperçu est prêt."));
}
render();
window.PrototypeState=state;
